<template><div><h1 class="text-3xl font-bold">Réglages</h1><p class="mt-2 text-[var(--muted)]">Valeurs éditables sans exposer les secrets d’environnement.</p><form class="card mt-8 max-w-2xl space-y-4" @submit.prevent="save"><label v-for="item in items" :key="item.key" class="block text-xs font-semibold">{{ labels[item.key]||item.key }}<input v-model="item.value" class="field mt-2"/></label><p class="text-xs leading-5 text-[var(--muted)]">Les secrets, clés S3 et clés API restent exclusivement dans les variables d’environnement.</p><p v-if="notice" class="text-sm text-emerald-700">{{ notice }}</p><button class="btn-primary">Enregistrer</button></form></div></template>
<script setup lang="ts">definePageMeta({middleware:'admin',layout:'admin'});useSeoMeta({title:'Réglages',robots:'noindex,nofollow'});const defaults=[{key:'default_gate_fields',value:'firstName,email,phone,domain'},{key:'lead_notification_email',value:'contact@novatrixai.com'}];const {data}=await useFetch<any>('/api/admin/settings',{default:()=>({items:[]})});const items=ref(data.value.items.length?data.value.items:defaults),notice=ref(''),labels:Record<string,string>={default_gate_fields:'Champs du formulaire ressource',lead_notification_email:'Email de notification'};async function save(){await $fetch('/api/admin/settings',{method:'PUT',body:{items:items.value}});notice.value='Réglages enregistrés.'}</script>
